/**
 * Unit tests for NumberUtils.isNumber to maximize branch and line coverage.
 */
public class NumberUtils_isNumber_TriageGen2Test {





    @Test
    public void testIsNumber_Decimals() {
        assertTrue("Decimal", NumberUtils.isNumber("123.45"));
        assertTrue("Decimal without leading zero", NumberUtils.isNumber(".45"));
        assertTrue("Decimal without trailing zero", NumberUtils.isNumber("123."));
        assertTrue("Negative decimal", NumberUtils.isNumber("-123.45"));
        assertFalse("Two decimals", NumberUtils.isNumber("123.45.67"));
        assertFalse("Decimal in exponent", NumberUtils.isNumber("123e1.5"));
    }








}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NumberUtils.isNumber to maximize branch and line coverage.
 */
public class NumberUtils_isNumber_TriageGen2Test {







    @Test
    public void testIsNumber_ScientificNotation() {
        assertTrue("Exponent lowercase", NumberUtils.isNumber("123e45"));
        assertTrue("Exponent uppercase", NumberUtils.isNumber("123E45"));
        assertTrue("Exponent with sign", NumberUtils.isNumber("123e+45"));
        assertTrue("Exponent with negative sign", NumberUtils.isNumber("123e-45"));
        assertTrue("Negative sign with exponent", NumberUtils.isNumber("-123e45"));
        assertFalse("Exponent without leading digit", NumberUtils.isNumber("e45"));
        assertFalse("Two exponents", NumberUtils.isNumber("123e45e67"));
        assertFalse("Exponent at the end", NumberUtils.isNumber("123e"));
        assertFalse("Exponent with sign but no digit", NumberUtils.isNumber("123e+"));
        assertFalse("Exponent with sign and dot", NumberUtils.isNumber("123e+.5"));
    }






}

package org.apache.commons.lang3.math;

import java.io.*;
