/**
 * Unit tests for NumberUtils.isNumber to maximize branch and line coverage.
 */
public class NumberUtils_isNumber_TriageGen2Test {









    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue("Hexadecimal lowercase", NumberUtils.isNumber("0x123"));
        assertTrue("Hexadecimal uppercase", NumberUtils.isNumber("0xABC"));
        assertTrue("Hexadecimal with sign", NumberUtils.isNumber("-0x123"));
        assertTrue("Hexadecimal mixed case", NumberUtils.isNumber("0x1a2B"));
        assertFalse("Hex prefix only", NumberUtils.isNumber("0x"));
        assertFalse("Hex with invalid chars", NumberUtils.isNumber("0xG12"));
        assertFalse("Hex with decimal", NumberUtils.isNumber("0x12.3"));
    }




}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NumberUtils.isNumber to maximize branch and line coverage.
 */
public class NumberUtils_isNumber_TriageGen2Test {











    @Test
    public void testIsNumber_Suffixes() {
        // Test d, D, f, F suffixes
        assertTrue("Integer suffix d", NumberUtils.isNumber("123d"));
        assertTrue("Integer suffix D", NumberUtils.isNumber("123D"));
        assertTrue("Float suffix f", NumberUtils.isNumber("123.45f"));
        assertTrue("Float suffix F", NumberUtils.isNumber("123.45F"));

        // Test l, L suffixes
        assertTrue("Long suffix l", NumberUtils.isNumber("123l"));
        assertTrue("Long suffix L", NumberUtils.isNumber("123L"));

        // Invalid suffixes
        assertFalse("Suffix with exponent L", NumberUtils.isNumber("123e5L"));
        assertFalse("Invalid suffix", NumberUtils.isNumber("123x"));

        // Edge case: suffix after digit check
        assertTrue("Digits with suffix", NumberUtils.isNumber("123f"));
        assertFalse("Suffix without digits", NumberUtils.isNumber("f"));
    }


}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NumberUtils.isNumber to maximize branch and line coverage.
 */
public class NumberUtils_isNumber_TriageGen2Test {













    @Test
    public void testIsNumber_ComplexEdgeCases() {
        // Testing the logic: while (i < sz || (i < sz + 1 && allowSigns && !foundDigit))
        // This covers the case where a sign follows an 'E' but no digits have been found yet
        assertFalse("Sign after E but no digits", NumberUtils.isNumber("123e-"));

        // Testing the end of loop logic
        assertTrue("Dot and digit", NumberUtils.isNumber(".1"));

        // Testing invalid characters
        assertFalse("Space in middle", NumberUtils.isNumber("12 3"));
        assertFalse("Space at start", NumberUtils.isNumber(" 123"));
        assertFalse("Special characters", NumberUtils.isNumber("123!"));
    }
}
